      ell(b, 15.5, cy, rx, ry, 1); ell(b, 15.5, cy - ry + 1, rx - 1, 5, 1);
      const sp = ri(R, 7, 11); for (let i = 0; i < 3; i++) { tri(b, 15 - rx + 1, cy - 4 + i * 2, 15 - rx - sp + i * 2, cy + 2 + i * 3, 15 - rx + 1, cy + 4 + i * 2, 4); }   // wings
